import collections,hashlib,json,math,re
from pathlib import Path
ROOT=Path('/Users/westbrook/Documents/repos/gossip-protocol')
RUN=ROOT/'results/benchmark-live-1'
BINDINGS={}
def sha(b):return hashlib.sha256(b).hexdigest()
def canonical(x):return json.dumps(x,sort_keys=True,ensure_ascii=True,allow_nan=False,separators=(',',':'))
def digest(x):return sha(canonical(x).encode())
def read(path,expected=None):
 p=Path(path).resolve(); assert p.is_relative_to(RUN)
 b=p.read_bytes(); h=sha(b)
 if expected is not None: assert h==expected,(str(p),h,expected)
 BINDINGS[str(p.relative_to(ROOT))]=h
 return json.loads(b)
def linked(row):return read(row['path'],row['sha256'])
freeze=read(RUN/'frozen-trajectories.json')
pre=read(RUN/'preregistered.json')
assert digest(pre['contract'])==freeze['contract_sha']
for name in ['benchmark_stage.py','benchmark_experiment.py','verification_probes.py']:
 p=RUN/'source-snapshot/gossip_harness'/name
 h=sha(p.read_bytes());assert h==pre['contract']['sources'][name]
 BINDINGS[str(p.relative_to(ROOT))]=h

def strict_parse(changes,role,context):
 key='probes.json' if role=='scout' else 'review.json'
 if not isinstance(changes,dict) or set(changes)!={key}:return None,'artifact_shape'
 text=changes[key]
 if not isinstance(text,str) or len(text.encode())>65536:return None,'missing_or_oversized_text'
 def pairs(rows):
  out={}
  for k,v in rows:
   if k in out:raise ValueError('duplicate_json_member')
   out[k]=v
  return out
 def nonfinite(_):raise ValueError('nonfinite_json')
 try: x=json.loads(text,object_pairs_hook=pairs,parse_constant=nonfinite)
 except json.JSONDecodeError as e:return None,f'json_syntax_error:{e.msg}'
 except (ValueError,RecursionError) as e:return None,str(e)
 if role=='scout':
  if not isinstance(x,dict) or set(x)!={'probes'} or not isinstance(x['probes'],list) or len(x['probes'])>4:return None,'scout_envelope_schema'
 else:
  if not isinstance(x,dict) or set(x)!={'candidate','action','notes','remaining','probes'}:return None,'review_envelope_schema'
  stack=[(x,0)]; count=0
  while stack:
   item,depth=stack.pop();count+=1
   if count>16384 or depth>32:return None,'review_json_tree_limits'
   if isinstance(item,float) and not math.isfinite(item):return None,'nonfinite_json'
   if isinstance(item,dict):stack.extend((v,depth+1) for v in item.values())
   elif isinstance(item,list):stack.extend((v,depth+1) for v in item)
  requirements={r for m in context['milestones'] for r in m['requirements']}
  if not isinstance(x['notes'],str) or len(x['notes'])>8192 or not isinstance(x['remaining'],list) or any(not isinstance(r,str) or r not in requirements for r in x['remaining']):return None,'review_notes_or_requirements'
  if len(set(x['remaining']))!=len(x['remaining']):return None,'review_duplicate_remaining'
  if x['candidate'] not in context['candidate_eligibility'] or x['action'] not in {'accept','repair','inspect'}:return None,'review_candidate_or_action'
  if not isinstance(x['probes'],list) or len(x['probes'])>4:return None,'review_probe_schema'
 return x,None

def hash_fields(v,path='$'):
 found=[]
 if isinstance(v,dict):
  for k,z in v.items():
   if k=='digest' and isinstance(z,str):found.append({'path':path+'.'+k,'value':z,'hex64':bool(re.fullmatch('[0-9a-f]{64}',z))})
   if k=='digests' and isinstance(z,dict):
    for q,s in z.items():
     if isinstance(s,str):found.append({'path':path+'.'+k+'.'+q,'value':s,'hex64':bool(re.fullmatch('[0-9a-f]{64}',s))})
   found+=hash_fields(z,path+'.'+str(k))
 elif isinstance(v,list):
  for i,z in enumerate(v):found+=hash_fields(z,path+f'[{i}]')
 return found

STAGES=[];CALLS=[];PROPOSALS=[];REVALIDATIONS=[];TRAJECTORIES=[]
for t in freeze['trajectories']:
 trajectory=read(RUN/t['run_id']/'trajectory.json',t['trajectory_sha256'])
 assert digest(trajectory['files'])==t['files_sha256']
 TRAJECTORIES.append({k:t[k] for k in ('run_id','project_id','policy','repetition','trajectory_sha256','files_sha256','evidence_sha256')})
 for art in t['stage_artifacts']:
  s=linked(art['result']); scouts=linked(art['scouts']);si=art['stage_index']
  assert trajectory['stages'][si]==s
  assert scouts==s['scouts']
  meta=dict(run_id=t['run_id'],project_id=t['project_id'],policy=t['policy'],repetition=t['repetition'],stage_index=si)
  stage=dict(meta,result=art['result'],scouts_artifact=art['scouts'],stage_files_sha256=digest(s['files']),stage_start_source_sha256=scouts['source_sha256'],initial_pool_sha256=s['initial_pool_sha256'])
  stage_calls=[]
  for call in art['requests']:
   cid=call['call_id']; role='scout' if cid.startswith('scout-') else 'reviewer' if cid.startswith('reviewer-') else None
   if role is None:continue
   req=linked(call['request']);result=linked(call['result'])
   assert result['role']==role and result['call_id']==cid
   context=json.loads(req['files']['verification-context.json']) if role=='reviewer' else None
   parsed,reason=strict_parse(result.get('changes'),role,context)
   row=dict(meta,role=role,call_id=cid,result=call['result'],request=call['request'],physical_dispatch=result['physical_dispatch'],parsed=parsed is not None,parse_failure_reason=reason,parsed_proposal_count=len(parsed['probes']) if parsed is not None else None)
   if role=='scout':
    scoutid='scout-'+cid.split('-')[2]
    retained=next(p for p in scouts['parses'] if p['scout_id']==scoutid)
    assert (retained['status']=='parsed')==row['parsed']
    assert retained['proposed_count']==row['parsed_proposal_count']
    row['scout_id']=scoutid
   else:row['review_round']=int(cid.split('-')[-1])
   CALLS.append(row);stage_calls.append(row)
  receiptcounts=collections.Counter()
  for ri,r in enumerate(s['probe_receipts']):
   rc=r['receipt']; role=r['origin'].get('source')
   pointer='/probe_receipts/'+str(ri)
   if r['mode']=='revalidate':
    REVALIDATIONS.append(dict(meta,pointer=pointer,result=art['result'],proposed=rc['proposed_count'],retained=len(rc['admitted_cases']),rejected=rc['rejected'],retired=rc['retired']))
    continue
   assert role in ('scout','reviewer')
   ps=r['envelope']['probes'];assert rc['proposed_count']==len(ps)
   admitted={q['proposal_index']:q for q in rc['admitted_cases']}
   rejected={q['index']:q for q in rc['rejected']}
   assert None not in rejected,(meta,ri,rc['rejected'])
   assert set(admitted)|set(rejected)==set(range(len(ps)))
   assert not set(admitted)&set(rejected)
   receiptcounts[role+'_proposed']+=len(ps);receiptcounts[role+'_admitted']+=len(admitted);receiptcounts[role+'_rejected']+=len(rejected)
   for pi,p in enumerate(ps):
    rejection=rejected.get(pi); outcome='admitted' if pi in admitted else 'rejected'
    if rejection and rejection.get('proposal_sha256'): assert rejection['proposal_sha256']==digest(p)
    row=dict(meta,role=role,origin=r['origin'],stage_result=art['result'],receipt_pointer=pointer,proposal_pointer=pointer+'/envelope/probes/'+str(pi),proposal_sha256=digest(p),proposal_index=pi,outcome=outcome,rejection_reason=rejection['reason'] if rejection else None)
    if isinstance(p,dict):
     row['requirement']=p.get('requirement');row['input_sha256']=digest(p['input']) if 'input' in p else None
     row['commands']=[z.get('op') if isinstance(z,dict) else None for z in p.get('input',{}).get('commands',[])] if isinstance(p.get('input'),dict) else []
     hashes=hash_fields(p.get('expected'));row['expected_digest_fields']=hashes;row['has_expected_digest_string']=bool(hashes)
     row['expected_json_chars']=len(canonical(p.get('expected')))
    if outcome=='admitted':row['case_id']=admitted[pi]['id']
    if rejection and rejection['reason']=='duplicate_input':
     matches=[q for q in r['envelope']['existing_cases'] if digest(q['input'])==row.get('input_sha256')]
     if matches:row['duplicate_of']=[{'id':q['id'],'kind':'generated_probe' if 'validation_policy' in q else 'public_case','origin':q.get('origin')} for q in matches]
     else:row['duplicate_of']=[{'id':q['id'],'kind':'same_batch_earlier_admission','origin':q.get('origin')} for j,q in admitted.items() if j<pi and q['input_sha256']==row.get('input_sha256')]
    PROPOSALS.append(row)
  stage['admission_counts']=dict(receiptcounts)
  stage['call_counts']={role:dict(calls=sum(c['role']==role for c in stage_calls),parsed_batches=sum(c['role']==role and c['parsed'] for c in stage_calls),rejected_envelopes=sum(c['role']==role and not c['parsed'] for c in stage_calls)) for role in ('scout','reviewer')}
  for role in ('scout','reviewer'):
   assert sum(c['parsed_proposal_count'] or 0 for c in stage_calls if c['role']==role)==receiptcounts[role+'_proposed']
  assert s['metrics']['invalid_reviews']==stage['call_counts']['reviewer']['rejected_envelopes']
  assert scouts['admitted']==receiptcounts['scout_admitted'] and scouts['rejected']==receiptcounts['scout_rejected']
  STAGES.append(stage)

def aggregate(selector=lambda x:True):
 ps=[p for p in PROPOSALS if selector(p)];cs=[c for c in CALLS if selector(c)]
 return {role:{'calls':sum(c['role']==role for c in cs),'parsed_batches':sum(c['role']==role and c['parsed'] for c in cs),'unparseable_or_controller_rejected_envelopes':sum(c['role']==role and not c['parsed'] for c in cs),'parsed_proposals':sum(p['role']==role for p in ps),'admitted_proposals':sum(p['role']==role and p['outcome']=='admitted' for p in ps),'rejected_proposals':sum(p['role']==role and p['outcome']=='rejected' for p in ps),'proposal_rejection_reasons':dict(collections.Counter(p['rejection_reason'] for p in ps if p['role']==role and p['outcome']=='rejected')),'envelope_rejection_reasons':dict(collections.Counter(c['parse_failure_reason'] for c in cs if c['role']==role and not c['parsed']))} for role in ('scout','reviewer')}
SUMMARY={'overall':aggregate(),'by_project':{domain:aggregate(lambda x:x['project_id']==domain) for domain in ('graph-patch','calendar-exchange')},'by_project_stage':{f'{domain}/stage-{si}':aggregate(lambda x:x['project_id']==domain and x['stage_index']==si) for domain in ('graph-patch','calendar-exchange') for si in (0,1)},'by_policy':{pol:aggregate(lambda x:x['policy']==pol) for pol in ('independent-four','sequential-four','strong-anchor')}}
print(json.dumps({'stage_count':len(STAGES),'trajectory_count':len(TRAJECTORIES),'summary':SUMMARY,'revalidation_count':len(REVALIDATIONS),'revalidated_probes':sum(r['proposed'] for r in REVALIDATIONS),'distinct_admitted_inputs':len({p['input_sha256'] for p in PROPOSALS if p['outcome']=='admitted'}),'admitted_instances':sum(p['outcome']=='admitted' for p in PROPOSALS)},indent=2))
# Save interim in scratch only. Final allowed artifact awaits the independent read-only observation.
Path('/tmp/benchmark_probe_admission_data.json').write_text(json.dumps(dict(freeze={k:freeze[k] for k in ('protocol','contract_sha','frozen_utc')},input_bindings=BINDINGS,trajectories=TRAJECTORIES,stages=STAGES,calls=CALLS,proposals=PROPOSALS,revalidations=REVALIDATIONS,summary=SUMMARY),indent=2)+'\n')
